const Festval_serch_details = (props) => {
  const [defaultArea, area] = useState("전국");
  const defaultDate = "월별";

  const [isSelect,setIsSelect] = useState(0); // 드롭메뉴_셀렉트
  const [isCalender,setIsCalender] = useState(0); // 드롭메뉴_캘린더

  const onClickItem = (e) =>{
    setIsSelect(0);    
    //console.log(e.target.innerText);
    area(e.target.innerText);        
  }

  const onClickCheck = (e) =>{    
    //console.log(e.target.id);w
    let divIdValue = e.target.id;
    if(divIdValue === "class_ground"){
      if(setIsCalender === 1) return setIsCalender(0);
      else return setIsSelect(1);
    }
    else if(divIdValue ==="class_date"){
      console.log(setIsSelect.State);
      if(setIsSelect === 1){
        return setIsSelect(0);
      }
      else{
        return setIsCalender(1);
      }      
    }
    else{
      alert("잘못된 접근!");
    }
  }
  
  const [areaCode, setAreaCode] = useState(null);
  //지역분류 코드 가져오기
  useEffect(() => {
    const Loging = async() => { // async를 사용하는 함수 따로 선언  

        const baseUrl = "http://apis.data.go.kr/B551011/KorService1/areaCode1";
        //const serviceKey = "";
        const serviceKey = "Av0j4qFKXlogzFTNST8uPV8AmR6bdc5h9gNecQv1RR7v92yhfpCYFHj19OoN6mlq00fxLxYyEif4u5cu2GP%2BQA%3D%3D";
        const MobileOS = "ETC";
        const MobileApp = "Nado";            
        const areaCode = "1";
        
        const type = "json";
        
        try{
          const response = await axios.get(
            baseUrl
            + "?serviceKey=" + serviceKey //인증키
            + "&MobileOS=" + MobileOS //OS 구분
            + "&MobileApp=" + MobileApp // 서비스명     
            + "&numOfRows=100"
            + "&_type=" + type // Response 객체 타입 (기본 : XML)
          );        
          
          //console.log(window.navigator.userAgent);          
          //console.log(response.data);
          setAreaCode(response.data.response.body.items.item);
        }catch(e){      
          console.log(e);
        }
      };
      Loging();
},[]);
  if(!areaCode){ return "null"; }

  return(
    <div className='search_box'>
        <div className='search_class'>                     
          <button id='class_ground' className='select_button' onClick={onClickCheck}>{defaultArea}</button>
          <button id='class_date' className='select_button' onClick={onClickCheck}>{defaultDate}</button>                       
          <div id="select_hidden">
            <ul id="area_selete" style={{display: isSelect ? "block" : "none"}}>   
              {Object.entries(areaCode).map(([rnum, {code, name}]) => (
                  <li className="select_item" onClick={onClickItem} key={code}>{name}</li>
                )
              )}                                     
            </ul>
            <div id="date_calender" style={{display: isCalender ? "block" : "none"}}>
              <ul className="calender_date calender_years">
                <li className="calender_item years_item">{props.today}</li>                
              </ul>
              <ul className="calender_date">
                {[...Array(12)].map((t, idx) => {
                  return <li className="calender_item" onClick={onClickItem}>{idx+1}월</li>
                })}                
              </ul>
            </div>
          </div>  
        </div>          
        
        <div className='thema_class'>
          <div className='thema_box'>#테마</div>
          <div className='thema_box'>#테마</div>
          <div className='thema_box'>#테마</div>
          <div className='thema_box'>#테마</div>
        </div>
      </div>
  );

};// Festval_search_detauls close


export default Festval_serch_details;
